import datetime
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
AYLAR = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
SIRA = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']


def sayi(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, word in ((10 ** 9, 'milyar'), (10 ** 6, 'milyon'), (1000, 'bin')):
        if n >= val:
            q = n // val
            n = n % val
            if val == 1000 and q == 1:
                parts.append('bin')
            else:
                parts.append(sayi(q) + ' ' + word)
    if n >= 100:
        h = n // 100
        parts.append(('' if h == 1 else ONES[h] + ' ') + 'yüz')
        n = n % 100
    if n >= 10:
        parts.append(TENS[n // 10])
        n = n % 10
    if n:
        parts.append(ONES[n])
    return ' '.join(p for p in parts if p)


def ek(text):
    t = str(text).strip().lower()
    vow = 'aeıioöuü'
    last = ''
    for ch in reversed(t):
        if ch in vow:
            last = ch
            break
    s = {'a': 'ı', 'ı': 'ı', 'e': 'i', 'i': 'i', 'o': 'u', 'u': 'u', 'ö': 'ü', 'ü': 'ü'}.get(last, 'i')
    d = 't' if t[-1:] in 'çfhkpsşt' else 'd'
    return "'" + d + s + 'r'


def tutar(x, cur):
    try:
        v = round(float(x) * 100)
    except Exception:
        return ''
    whole, frac = v // 100, v % 100
    if cur == 'TL':
        return sayi(whole) + (' lira ' + sayi(frac) + ' kuruş' if frac else ' Türk Lirası')
    small = {'USD': ('dolar', 'sent', 'Dolar'), 'EUR': ('euro', 'sent', 'Euro'), 'GBP': ('sterlin', 'peni', 'İngiliz Sterlini')}[cur]
    return sayi(whole) + (' ' + small[0] + ' ' + sayi(frac) + ' ' + small[1] if frac else ' ' + small[2])


