    d = tarih_parse(s) if not isinstance(s, datetime.date) else s
    if not d:
        return ''
    return str(d.day) + ' ' + AYLAR[d.month] + ' ' + str(d.year)


def tarih_ek(s):
    d = tarih_parse(s)
    if not d:
        return ''
    return tarih(d) + ek(sayi(d.year))


